node -e '
import { spawn } from "node:child_process";

const srv = spawn("npx", ["next", "start", "-p", "4010"], { stdio: "pipe" });
await new Promise((resolve) => {
  srv.stdout.on("data", (d) => {
    if (d.toString().includes("Ready")) resolve();
  });
});

async function fetchTimed(path) {
  const start = performance.now();
  const res = await fetch("http://localhost:4010" + path);
  const reader = res.body.getReader();
  const chunks = [];
  const decoder = new TextDecoder();
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push({ t: Math.round(performance.now() - start), text: decoder.decode(value) });
  }
  return { status: res.status, totalMs: Math.round(performance.now() - start), chunks };
}

const r1 = await fetchTimed("/products/lamp?currency=EUR");
const r2 = await fetchTimed("/products/lamp?currency=EUR");
const r3 = await fetchTimed("/products/lamp");
const r4 = await fetchTimed("/products/vase?currency=EUR");

console.log("R1 chunks:", r1.chunks.map(c => ({ t: c.t, hasFrame: c.text.includes("Signal Shop collection"), hasProduct: c.text.includes("Brass lamp") && c.text.includes("EUR 110.40"), hasRelated: c.text.includes("Stone vase") })));
console.log("R2 chunks:", r2.chunks.map(c => ({ t: c.t, hasFrame: c.text.includes("Signal Shop collection"), hasProduct: c.text.includes("Brass lamp") && c.text.includes("EUR 110.40"), hasRelated: c.text.includes("Stone vase") })));
console.log("R3 text check:", r3.chunks.map(c => c.text).join("").includes("USD 120.00"));
console.log("R4 text check:", r4.chunks.map(c => c.text).join("").includes("Stone vase") && r4.chunks.map(c => c.text).join("").includes("EUR 73.60"));

srv.kill();
'
